        recent = sorted(events, key=lambda r: str(r["at"]))[-recent_n:]

        result = {"success": True, "campaign": camp, "player_characters": pcs,
                  "npcs": npcs, "locations": members("myth-location"),
                  "factions": members("myth-faction"),
